package net.minecraft.world.item;public class ItemStack {public final String key;public int count;public final int max;public ItemStack(String key,int count,int max){this.key=key;this.count=count;this.max=max;}public boolean isEmpty(){return count==0;}public int getCount(){return count;}public int getMaxStackSize(){return max;}public void setCount(int c){count=c;}public void shrink(int c){count-=c;}public ItemStack copy(){return new ItemStack(key,count,max);}public static boolean isSameItemSameComponents(ItemStack a,ItemStack b){return a.key.equals(b.key);}}
